.button { display: inline-flex; align-items: center; justify-content: center; gap: 20px; min-height: 54px; padding: 16px 22px; border: 1px solid var(--button); border-radius: 3px; color: #171615; background: var(--button); font-size: 14px; font-weight: 700; line-height: 1.3; text-decoration: none; transition: transform 140ms var(--ease-out), background-color 160ms ease; }
.button:active { transform: scale(.98); }
