.recall-experiment { color: #242323; --ink: #242323; --muted: #615d5a; --paper: #f7eeeb; --accent: #b3342a; margin-top: 24px; padding: 24px 28px; background: #f7eeeb; }
.recall-instruction { font-size: 14px; line-height: 1.6; min-height: 45px; font-weight: 500; }
.recall-stage { min-height: 180px; display: flex; align-items: center; padding-block: 20px; }
.recall-words { display: grid; gap: 5px; font-size: clamp(30px, 3vw, 40px); line-height: 1.16; font-weight: 550; letter-spacing: -.02em; }
.recall-question { font-size: 36px; line-height: 1.15; letter-spacing: -.025em; }
.recall-controls { display: flex; flex-wrap: wrap; gap: 12px 18px; align-items: center; }
.button-ink { --button: #242323; color: #fff; }
.recall-controls .button { font-size: 13px; gap: 14px; padding-inline: 17px; }
.recall-reset { color: #242323; background: transparent; border: 0; min-height: 44px; padding: 10px 0; font-size: 14px; text-decoration: underline; text-underline-offset: 4px; }
.recall-explanation { margin-top: 23px; padding-top: 18px; border-top: 1px solid #cdb7b0; font-size: 16px; }
.recall-explanation strong { display: block; font-weight: 600; margin-bottom: 8px; }
.recall-experiment :focus-visible { outline-color: #b3342a; }
@media (max-width: 1100px) and (min-width: 768px) {
  .recall-experiment { padding-inline: 22px; }
}
@media (max-width: 767px) {
  .recall-experiment { padding: 22px 24px; margin-top: 20px; }
  .recall-instruction { font-size: 14px; }
  .recall-stage { min-height: 180px; }
  .recall-words { font-size: 35px; }
  .recall-question { font-size: 33px; }
  .recall-controls .button { font-size: 13px; padding-inline: 15px; gap: 12px; }
}
@media (max-width: 359px) {
  .recall-experiment { padding-inline: 20px; }
  .recall-words { font-size: 30px; }
  .recall-controls .button { font-size: 12px; }
}
.recall-experiment { position: relative; padding: 28px 28px 30px 43px; background-color: #f7eeeb; background-image: linear-gradient(90deg, transparent 24px, #d7a59e 24px, #d7a59e 25px, transparent 25px); border-radius: 2px 3px 8px 1px; box-shadow: 2px 4px 10px rgb(0 0 0 / .1); }
.recall-experiment::before { content: ''; position: absolute; left: 9px; top: 28px; bottom: 25px; width: 6px; background-image: radial-gradient(circle, #6d5a54 2px, transparent 2.6px); background-size: 6px 30px; }
.recall-steps { display: grid; grid-template-columns: .85fr 1.3fr .85fr; list-style: none; gap: 9px; padding: 0 0 24px; margin: 0; }
.recall-steps li { position: relative; text-align: center; font-size: 13px; font-weight: 500; line-height: 1.3; padding: 11px 3px; border: 1px solid #ad8d83; border-radius: 38% 5% 20% 6% / 8% 36% 7% 30%; }
.recall-steps li:nth-child(2) { transform: rotate(2deg); }
.recall-steps li[aria-current=step] { color: #91281f; font-weight: 700; border: 2px solid #b3342a; padding: 10px 2px; background: #fffdf7; }
.recall-instruction { min-height: 45px; }
.recall-stage { min-height: 174px; }
@media (max-width: 1100px) and (min-width: 768px) {
  .recall-experiment { padding-right: 22px; padding-left: 36px; }
  .recall-steps { gap: 5px; }
  .recall-steps li { font-size: 12px; }
}
@media (max-width: 767px) {
  .recall-experiment { padding: 24px 20px 27px 35px; }
  .recall-steps { gap: 5px; padding-bottom: 22px; }
  .recall-steps li { font-size: 12px; }
  .recall-stage { min-height: 174px; }
  .recall-words { font-size: 33px; }
  .recall-controls .button { padding-inline: 14px; font-size: 12px; gap: 10px; }
}
@media (max-width: 359px) {
  .recall-experiment { padding-left: 32px; padding-right: 16px; }
  .recall-steps { grid-template-columns: .8fr 1.25fr .85fr; }
  .recall-steps li { font-size: 12px; }
  .recall-words { font-size: 28px; }
  .recall-controls .button { padding-inline: 11px; gap: 7px; font-size: 12px; }
}

:host{font-family:"Bricolage Grotesque Variable",sans-serif;--paper:#f7f6f2;--surface:#fffefd;--ink:#242323;--muted:#615d5a;--rule:#d4cfcb;--accent:#b3342a;--button:#e85448;--brand-red:#e85448;--drawing-paper:#fffdf7;--paper-edge:#c7bfb7;--ease-out:cubic-bezier(.23,1,.32,1);color:#242323}*{box-sizing:border-box}[hidden]{display:none!important}p,h3,ul{margin:0}p{line-height:1.7}button,input,textarea{font:inherit}button{cursor:pointer}:focus-visible{outline:3px solid var(--accent);outline-offset:5px}

.workshop-section { background: #252221; color: #f8f4f0; --paper: #252221; --surface: #302b29; --ink: #f8f4f0; --muted: #d3c9c1; --rule: #5b504b; --accent: #f18c7e; --tint: #352c29; }
.workshop-shell { padding-block: 64px; }
.workshop-programme { display: grid; grid-template-columns: 1.13fr 1fr; gap: 50px; align-items: start; }
.workshop { border-top: 1px solid var(--rule); border-bottom: 1px solid var(--rule); scroll-margin-top: 100px; }
.workshop-other .workshop + .workshop { border-top: 0; }
.workshop summary { display: flex; justify-content: space-between; gap: 20px; align-items: center; padding: 23px 0; cursor: pointer; list-style: none; }
.workshop summary > .ph { font-size: 24px; }
.workshop-name { display: flex; flex-direction: column; gap: 9px; font-size: clamp(26px, 2.7vw, 36px); line-height: 1.16; letter-spacing: -.025em; font-weight: 600; }
.workshop-name > span { font-size: 13px; color: var(--muted); letter-spacing: 0; font-weight: 450; }
.workshop[open] > summary { color: var(--accent); }
.workshop[open] > summary > .ph-plus { transform: rotate(45deg); }
.workshop-content { font-size: 16px; padding-bottom: 26px; }
.workshop-content > p { color: var(--muted); max-width: 48ch; margin-bottom: 18px; }
.workshop-content ul { font-size: 16px; }
.workshop-context { margin-top: 30px; }
.workshop-context img { width: 100%; aspect-ratio: 1.12; object-fit: cover; object-position: 50% 70%; }
.workshop-context figcaption { padding-top: 15px; font-size: 16px; }
.workshop-notice { display: grid; grid-template-columns: 1fr 160px; gap: 60px; align-items: center; margin-top: 42px; border-top: 1px solid var(--rule); padding: 36px 0 0; }
.workshop-notice h3 { font-size: 34px; margin-top: 14px; }
.workshop-notice p:not(.availability):not(.small-text) { font-size: 16px; max-width: 60ch; margin-top: 18px; }
.workshop-notice .text-link { margin-top: 12px; }
.workshop-notice .small-text { color: var(--muted); margin-top: 15px; max-width: 65ch; }
.workshop-section :focus-visible { outline-color: #f18c7e; }

@media (hover: hover) and (pointer: fine) {
  .workshop > summary:hover { color: var(--accent); }
}
@media (max-width: 1100px) and (min-width: 768px) {
  .workshop-programme { gap: 34px; }
}
@media (max-width: 767px) {
  .workshop-shell { padding-block: 42px; }
  .workshop-programme { grid-template-columns: 1fr; gap: 26px; }
  .workshop summary { padding-block: 22px; }
  .workshop-name { font-size: 28px; }
  .workshop-name > span { font-size: 13px; }
  .workshop-content { padding-bottom: 24px; }
  .workshop-context { display: none; }
  .workshop-notice { grid-template-columns: 1fr; gap: 0; margin-top: 28px; padding-top: 26px; }
  .workshop-notice h3 { font-size: 30px; }
}
.workshop-section { position: relative; }
.workshop-section::before, .workshop-section::after { content: ''; position: absolute; left: 0; right: 0; height: 14px; background: var(--paper-outside, #f7f6f2); }
.workshop-section::before { top: -1px; clip-path: polygon(0 0,100% 0,100% 30%,96% 65%,92% 34%,86% 90%,82% 30%,75% 67%,69% 31%,62% 88%,55% 40%,48% 79%,41% 26%,33% 81%,26% 36%,20% 78%,14% 32%,7% 73%,0 28%); }
.workshop-section::after { bottom: -1px; transform: rotate(180deg); clip-path: polygon(0 0,100% 0,100% 30%,92% 65%,86% 34%,78% 90%,71% 30%,64% 67%,57% 31%,50% 88%,43% 40%,36% 79%,29% 26%,22% 81%,15% 36%,8% 78%,0 28%); }
.workshop-shell { padding-block: 74px; }
.workshop-sketch { position: absolute; right: 10px; top: 4px; width: 190px; transform: rotate(9deg); }
.workshop-sketch .red-pen { stroke: #f18c7e; }
.workshop-context { position: relative; padding: 12px 12px 0; background: #fffdf7; color: #242323; transform: rotate(2deg); }
.workshop-context::before { content: ''; position: absolute; z-index: 1; width: 90px; height: 27px; top: -11px; left: 43%; background: #e1cbb5; transform: rotate(-10deg); opacity: .9; }
.workshop-context figcaption { padding: 16px 6px 20px; }
@media (max-width: 1100px) and (min-width: 768px) {
  .workshop-sketch { width: 145px; right: 0; }
}
@media (max-width: 767px) {
  .workshop-shell { padding-block: 53px; }
  .workshop-sketch { width: 75px; right: 0; top: 49px; }
}
@media (max-width: 359px) {
  .workshop-sketch { display: none; }
}

